using Cogpunk.Core.Templates;
using Microsoft.Xna.Framework;
using Terraria;
using Terraria.ID;
using Terraria.ModLoader;

namespace Cogpunk.Content.Coghaven.Tiles
{
	/// <summary>
	/// Cinnabar Lacquer (2026-11-06): red lacquered boards with gilt nail heads, the pillars and beams of Coghaven's palace. Generated by <see cref="Generation.CoghavenPass"/>; seamless clump art from art/coghaven/make_coghaven_art.py.
	/// </summary>
	public class CinnabarLacquerTile : CogpunkTile
	{
		public override void SetStaticDefaults() {
			TileID.Sets.GeneralPlacementTiles[Type] = false;   // later world-gen features (other mods) keep off the palace
			Main.tileSolid[Type] = true;
			Main.tileBlockLight[Type] = true;
			DustType = DustID.DynastyWood;
			HitSound = SoundID.Dig;
			AddMapEntry(new Color(168, 44, 42), CreateMapEntryName());
			RegisterItemDrop(ModContent.ItemType<Items.CinnabarLacquer>());
		}
	}
}
